<script>(function(){var w=document.querySelector('[data-rvs]');if(!w)return;var cards=w.querySelectorAll('.wu-rv'),track=w.querySelector('.wu-rv-grid'),prev=w.querySelector('[data-rv-prev]'),next=w.querySelector('[data-rv-next]');var fit=function(){cards.forEach(function(c){var t=c.querySelector('.wu-rv-text'),b=c.querySelector('.wu-rv-more');if(c.classList.contains('is-open'))return;b.hidden=!(t.scrollHeight>t.clientHeight+2);});};cards.forEach(function(c){var b=c.querySelector('.wu-rv-more');b.addEventListener('click',function(){var on=!c.classList.contains('is-open');c.classList.toggle('is-open',on);b.setAttribute('aria-expanded',String(on));b.textContent=on?'Show less':'Read more';});});fit();addEventListener('resize',fit);addEventListener('load',fit);var step=function(){return cards[0].getBoundingClientRect().width+16;};var upd=function(){prev.disabled=track.scrollLeft<4;next.disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-4;};prev.addEventListener('click',function(){track.scrollBy({left:-step()});});next.addEventListener('click',function(){track.scrollBy({left:step()});});track.addEventListener('scroll',upd,{passive:true});addEventListener('resize',upd);upd();})();</script>
